//! Python `str` behaviours the Config and palette code reproduce: `isspace`, `strip()`,
//! `split()`, `splitlines()`, `isprintable` (for `repr`), `isdigit` and the decimal digits
//! `int()` and `float()` accept, and `float(str)` itself.
//!
//! The Unicode property tables in `pyunicode/tables.rs` are generated by
//! `scripts/gen_pyunicode_tables.py` from Python 3.11's `unicodedata` (Unicode 14.0.0).
//! Python 3.12 and 3.13 use newer Unicode versions; the differences are confined to
//! characters assigned since, which no config value or palette file in the tests uses.

#[rustfmt::skip]
mod tables;

pub use tables::UNICODE_VERSION;

fn in_ranges(c: char, ranges: &[(u32, u32)]) -> bool {
    let c = c as u32;
    ranges
        .binary_search_by(|&(lo, hi)| {
            if hi < c {
                std::cmp::Ordering::Less
            } else if lo > c {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// `c.isspace()`.
pub fn is_space(c: char) -> bool {
    in_ranges(c, tables::SPACE)
}

/// `c.isprintable()`.
pub fn is_printable(c: char) -> bool {
    !in_ranges(c, tables::NOT_PRINTABLE)
}

/// The value of a decimal digit (`c.isdecimal()`, any script), as `int()` reads it.
pub fn decimal_value(c: char) -> Option<u32> {
    let c = c as u32;
    let i = tables::DECIMAL_ZEROS.partition_point(|&z| z <= c);
    if i == 0 {
        return None;
    }
    let zero = tables::DECIMAL_ZEROS[i - 1];
    (c - zero < 10).then_some(c - zero)
}

/// `c.isdigit()`: decimal digits plus digits such as superscripts and circled digits.
pub fn is_digit(c: char) -> bool {
    decimal_value(c).is_some() || in_ranges(c, tables::DIGIT_NOT_DECIMAL)
}

/// `s.strip()` (no argument: Unicode whitespace).
pub fn strip(s: &str) -> &str {
    s.trim_matches(is_space)
}

/// `s.split()` (no argument: runs of Unicode whitespace, no empty items).
pub fn split_whitespace(s: &str) -> Vec<&str> {
    s.split(is_space).filter(|p| !p.is_empty()).collect()
}

fn is_line_break(c: char) -> bool {
    matches!(
        c,
        '\n' | '\r'
            | '\x0b'
            | '\x0c'
            | '\x1c'
            | '\x1d'
            | '\x1e'
            | '\u{85}'
            | '\u{2028}'
            | '\u{2029}'
    )
}

/// `s.splitlines()`: lines without their terminators; `\r\n` is one terminator and a
/// trailing terminator does not start an empty line.
pub fn splitlines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut chars = s.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        if is_line_break(c) {
            out.push(&s[start..i]);
            let mut end = i + c.len_utf8();
            if c == '\r' {
                if let Some(&(j, '\n')) = chars.peek() {
                    chars.next();
                    end = j + 1;
                }
            }
            start = end;
        }
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

/// `int(s)` for a string of `isdigit` characters (as `parse_gpl` calls it): the value,
/// saturated at `u64::MAX`, or `None` where Python raises ValueError (a digit that is not
/// decimal, such as '²').
pub fn int_of_digits(s: &str) -> Option<u64> {
    let mut v: u64 = 0;
    for c in s.chars() {
        let d = decimal_value(c)?;
        v = v.saturating_mul(10).saturating_add(u64::from(d));
    }
    (!s.is_empty()).then_some(v)
}

/// `float(s)` for a `str`: `None` where Python raises ValueError.
///
/// CPython maps non-ASCII whitespace to ' ' and non-ASCII decimal digits to ASCII (any other
/// character from U+007F up makes the string invalid), strips ASCII whitespace, accepts
/// underscores only between two digits and then parses `[sign](digits[.digits]|.digits)
/// [e[sign]digits]`, `inf`, `infinity` or `nan` (any case). Rust's parser accepts the same
/// grammar once the underscores are gone, and both round correctly.
pub fn parse_float(s: &str) -> Option<f64> {
    let mut ascii = String::with_capacity(s.len());
    for c in s.chars() {
        if (c as u32) < 127 {
            ascii.push(c);
        } else if is_space(c) {
            ascii.push(' ');
        } else {
            ascii.push(char::from_digit(decimal_value(c)?, 10)?);
        }
    }
    let t = ascii.trim_matches(|c: char| matches!(c, ' ' | '\t' | '\n' | '\r' | '\x0b' | '\x0c'));
    let mut text = String::with_capacity(t.len());
    let mut prev = '\0';
    for c in t.chars() {
        if c == '_' {
            if !prev.is_ascii_digit() {
                return None;
            }
        } else {
            if prev == '_' && !c.is_ascii_digit() {
                return None;
            }
            text.push(c);
        }
        prev = c;
    }
    if prev == '_' {
        return None;
    }
    // Rust also accepts these; Python's grammar does not include them.
    if text.is_empty() || text.contains(|c: char| c.is_whitespace()) {
        return None;
    }
    text.parse::<f64>().ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spaces_and_strip() {
        assert!(is_space(' ') && is_space('\x1c') && is_space('\u{3000}'));
        assert!(!is_space('\u{200b}') && !is_space('a'));
        assert_eq!(strip("\u{a0} ab \t"), "ab");
        assert_eq!(split_whitespace("  1\t2\u{2003}3 "), vec!["1", "2", "3"]);
    }

    #[test]
    fn splitlines_like_python() {
        assert_eq!(splitlines(""), Vec::<&str>::new());
        assert_eq!(
            splitlines("a\nb\r\nc\rd\x0be\u{2028}f\n"),
            vec!["a", "b", "c", "d", "e", "f"]
        );
        assert_eq!(splitlines("\n\n"), vec!["", ""]);
        assert_eq!(splitlines("a\r\r\nb"), vec!["a", "", "b"]);
    }

    #[test]
    fn digits() {
        assert_eq!(decimal_value('7'), Some(7));
        assert_eq!(decimal_value('\u{663}'), Some(3));
        assert_eq!(decimal_value('\u{ff15}'), Some(5));
        assert_eq!(decimal_value('a'), None);
        assert!(is_digit('\u{b2}') && decimal_value('\u{b2}').is_none());
        assert_eq!(int_of_digits("0255"), Some(255));
        assert_eq!(int_of_digits("\u{b2}"), None);
    }

    #[test]
    fn printable() {
        assert!(is_printable('a') && is_printable(' ') && is_printable('\u{2713}'));
        assert!(!is_printable('\n') && !is_printable('\u{a0}') && !is_printable('\u{ad}'));
    }

    #[test]
    fn float_strings() {
        let ok = |s: &str| parse_float(s).unwrap();
        assert_eq!(ok(" 1.5 "), 1.5);
        assert_eq!(ok("1_000.2_5"), 1000.25);
        assert_eq!(ok("1."), 1.0);
        assert_eq!(ok(".5e-1_0"), 0.5e-10);
        assert_eq!(ok("-InFiNiTy"), f64::NEG_INFINITY);
        assert!(ok("+nan").is_nan());
        assert_eq!(ok("\u{663}.\u{665}"), 3.5);
        assert_eq!(ok("\u{3000}2\u{a0}"), 2.0);
        for bad in [
            "", " ", "_1", "1_", "1__0", "1_.5", "1._5", "abc", "1e", "e5", ".", "0x10", "1 2",
            "\u{7f}1", "\x1c1", "1\u{b2}", "in f",
        ] {
            assert!(parse_float(bad).is_none(), "{bad:?}");
        }
    }
}
